function rotateRight(node) {
  const up = node.left;          // the left child moves up
  node.left = up.right;          // its right subtree moves across to node
  up.right = node;               // node becomes its right child
  return up;                     // the new root of this subtree
}

TreeNode rotateRight(TreeNode node) {
    TreeNode up = node.left;          // the left child moves up
    node.left = up.right;             // its right subtree moves across to node
    up.right = node;                  // node becomes its right child
    return up;                        // the new root of this subtree
}

TreeNode* rotateRight(TreeNode* node) {
    TreeNode* up = node->left;        // the left child moves up
    node->left = up->right;           // its right subtree moves across to node
    up->right = node;                 // node becomes its right child
    return up;                        // the new root of this subtree
}
